"use strict";
const phoneModels={
 nokia3310:{name:'Nokia 3310 风格',short:'NOKIA',era:'2000 · 黑白屏',class:'mono',note:'黑白屏、实体键盘与贪吃蛇的记忆'},
 symbian:{name:'Nokia 6600 风格',short:'NOKIA',era:'2003 · 彩屏',class:'symbian',note:'彩色屏幕与早期智能手机的记忆'},
 razr:{name:'Motorola V3 风格',short:'MOTOROLA',era:'2004 · 翻盖',class:'razr',note:'金属翻盖、蓝色键光与掌心的轻薄'},
 walkman:{name:'随身听手机风格',short:'WALKMAN',era:'2005 · 音乐',class:'walkman',note:'橙色按键、音乐快捷键与随身听的记忆'},
 iphone:{name:'初代 iPhone 风格',short:'',era:'2007 · 触屏',class:'iphone',note:'黑色玻璃、拟物图标与最初的触屏时代'}
};
const phoneApps=[['home','首页','⌂'],['news','新闻','报'],['music','音乐','♪'],['videos','视频','▶'],['books','小说','书'],['games','游戏','▦'],['sms','短信','✉'],['ads','广告','AD'],['photos','壁纸','▧'],['gallery','图文','图'],['magazines','报刊','刊']];
let phoneState={model:'symbian',app:'home',page:0,article:null,draft:'',wallpaper:'blue',sent:[],film:0,book:0,chapter:0,captureBusy:false};
try{const p=JSON.parse(localStorage.getItem('archaeo-phone-lab')||'{}');if(Object.hasOwn(phoneModels,p.model))phoneState.model=p.model;if(['blue','sunset','stars','green'].includes(p.wallpaper))phoneState.wallpaper=p.wallpaper;if(Array.isArray(p.sent))phoneState.sent=p.sent.filter(x=>x&&typeof x.text==='string'&&typeof x.reply==='string').slice(-12).map(x=>({text:x.text.slice(0,160),reply:x.reply.slice(0,240)}));}catch{}
function savePhone(){try{localStorage.setItem('archaeo-phone-lab',JSON.stringify({model:phoneState.model,wallpaper:phoneState.wallpaper,sent:phoneState.sent.slice(-12)}));}catch{}}
function openPhoneLab(app){$('#modal').close();if(app){phoneState.app=app;phoneState.article=null;phoneState.page=0;}navigate({type:'phone',name:'口袋时光机',url:'archaeo://phone'});}
function phoneButton(app,title,icon){return `<button data-phone-app="${app}" class="phone-app-icon app-${app}"><b>${icon}</b><span>${title}</span></button>`;}
function phoneScreen(){
 const s=phoneState;
 if(s.app==='magazines')return phoneMagazineMarkup();
 if(s.app==='gallery')return phoneGalleryMarkup();
 if(s.app==='home')return `<div class="phone-standby"><div class="phone-digital-clock">${year()===String(new Date().getFullYear())?'12:00':'20:04'}</div><div class="phone-date">${date.replaceAll('-',' / ')}<br>中国移动 · 时光网络</div><div class="phone-home-grid">${phoneApps.filter(x=>x[0]!=='home').map(([a,t,i])=>phoneButton(a,t,i)).join('')}</div><div class="phone-home-tip">按数字键 / 点图标，开始探索</div></div>`;
 if(s.app==='news'){
  if(s.article!==null){const i=s.article,e=yearEvents[year()]?.[i];if(!e)return '<p>请返回新闻列表。</p>';const detail=eventDetails[`${year()}-${i}`];const paras=detail?.sections?.flatMap(x=>x.paragraphs)||detail?.paragraphs||[e[1]];return `<div class="phone-paper"><button data-phone-news-back>‹ 新闻列表</button><h2>${escapeHTML(e[1])}</h2><small>${year()} · ${escapeHTML(e[0])} / 历史资料版</small>${paras.slice(0,8).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}<button data-news-year="${year()}" data-news-index="${i}">在浏览器里读完整资料</button></div>`;}
  const rows=yearEvents[year()]||[];return `<div class="phone-wap-title">${year()} 年度新闻</div><div class="phone-news-list">${rows.map((r,i)=>`<button data-phone-news="${i}"><small>${r[0]}</small>${escapeHTML(r[1])}</button>`).join('')}</div><p class="phone-small-note">十篇精选长文 · 全年回顾<br>新闻中心另有 ${yearbookCounts[year()]||0} 条年表记录。</p><button data-news-center>查看更多年度记录</button>`;
 }
 if(s.app==='music')return `<div class="phone-player"><div class="phone-disc"><i>♪</i></div><b>${escapeHTML(memoryTracks[memoryTrack].name)}</b><small>${escapeHTML(memoryTracks[memoryTrack].credit)}</small><div class="phone-eq">▂ ▅ ▃ ▇ ▄ ▆ ▂</div><div class="phone-play-actions"><button data-phone-track="prev">|◀</button><button data-music-toggle>${$('#retro-audio').paused?'▶ 播放配乐':'Ⅱ 暂停配乐'}</button><button data-phone-track="next">▶|</button></div><p>${memoryTracks.map((t,i)=>`${i===memoryTrack?"▶":"0"+(i+1)}　${escapeHTML(t.name)}`).join("<br>")}</p><button data-ad-sms="铃声01">用短信领取一张铃声卡</button></div>`;
 if(s.app==='videos'){const films=eraFilms.filter(f=>f.year<=Number(year()));return `<div class="phone-wap-title">掌上影院 · ${year()}</div>${films.length?films.map((f,i)=>`<div class="phone-film"><h3>${escapeHTML(f.title)}</h3><video controls playsinline preload="none" src="${f.src}" aria-label="手机影院 ${escapeHTML(f.title)}"></video><small>${escapeHTML(f.credit)}<br><a href="${f.source}" target="_blank" rel="noopener noreferrer">影片来源</a> · <a href="${f.license}" target="_blank" rel="noopener noreferrer">${escapeHTML(f.licenseLabel||"CC BY 许可")}</a> · 网络播放</small></div>`).join(''):'<div class="phone-video-placeholder"><b>▶ 宽频时代</b><p>这个年份暂未整理可直接播放的授权影片。</p><button data-era-media>去当年的视频站看看</button><small>2001年起有开放影像档案可播放。</small></div>'}<p class="phone-small-note">影片与外部存档画面可能无法导出截图。手机外壳与本地页面可以保存。</p>`;}
 if(s.app==='books')return phoneBookMarkup();
 if(s.app==='games')return `<div class="phone-wap-title">掌中游戏厅</div><div class="phone-game-list"><button data-javame-room>JAVA 真正的 JAR 程序 <small>贪吃蛇 / 计算器 / 记事本</small></button><button data-phone-snake>▦ 贪吃蛇 <small>方向键 / 2 4 6 8</small></button><button data-arcade="mines">◇ 扫雷 <small>避开地雷，解开方格</small></button><button data-arcade="blocks">▥ 方块拼图 <small>方向操作，挑战分数</small></button><button data-scene="garden">田 开心菜园 <small>播种、浇水、收获</small></button><button data-scene="wutang">武 精武堂 <small>练功闯关，文字江湖</small></button></div><p class="phone-small-note">原创重制小游戏 · 成绩仅存本机</p>`;
 if(s.app==='snake')return renderPhoneSnake();
 if(s.app==='sms')return `<div class="phone-wap-title">短信 · ${s.sent.length} 封</div><div class="phone-sms-form"><label>收件人 <input value="106XXXX（本机演示）" readonly aria-label="演示短信收件人"></label><label>短信内容 <textarea id="phone-sms-text" maxlength="160" placeholder="试试：铃声01 / 壁纸01 / 游戏01">${escapeHTML(s.draft)}</textarea></label><button data-phone-send>发送体验短信</button><small>只在本机模拟，不联网发短信、不收费。</small></div><div class="phone-sms-thread">${s.sent.slice().reverse().map(m=>`<div class="sms-bubble outgoing">${escapeHTML(m.text)}</div><div class="sms-bubble incoming">${escapeHTML(m.reply)}</div>`).join('')||'<p>收件箱：<br>欢迎回到掌中世界。翻到杂志封底，找一个代码发来试试。</p>'}</div>`;
 if(s.app==='ads')return `<div class="phone-wap-title">杂志封底 · 广告页</div>${advertsForYear().map(ad=>`<div class="phone-classified"><b>${escapeHTML(ad.title)}</b><p>${escapeHTML(ad.copy)}</p><small>编辑 ${escapeHTML(ad.code)} 到 106XXXX</small><button data-ad-sms="${ad.code}">编辑体验短信</button></div>`).join('')}<p class="phone-small-note">怀旧创作广告 · 非真实服务</p>`;
 if(s.app==='photos')return `<div class="phone-wap-title">我的壁纸</div><div class="phone-wallpapers">${[['blue','蓝色星空'],['sunset','落日海岸'],['stars','像素宇宙'],['green','绿色回忆']].map(([id,t])=>`<button class="wallpaper-${id}" data-phone-wallpaper="${id}"><i></i><span>${t}</span>${s.wallpaper===id?'<b>已使用</b>':''}</button>`).join('')}</div><p class="phone-small-note">原创渐变与像素壁纸，不是历史原机资源。</p>`;
 return '';
}
function renderPhoneLab(){const m=phoneModels[phoneState.model];return `<section class="phone-lab"><header class="lab-heading"><div><small>POCKET TIME MACHINE / 口袋时光机</small><h1>把那年的手机，握回手里。</h1><p>点按实体键、翻翻短信和杂志封底，留下属于你的年代截图。</p></div><button data-gadget-open>MP3 / MP4 / 词典</button><button data-action="home">返回浏览器首页</button></header><div class="lab-toolbar"><label>选择手机 <select id="phone-model-select" aria-label="选择复古手机">${Object.entries(phoneModels).map(([id,x])=>`<option value="${id}" ${id===phoneState.model?'selected':''}>${x.name} · ${x.era}</option>`).join('')}</select></label><button data-capture-phone>▧ 保存手机截图</button><button data-ad-magazine>翻看杂志封底</button><button data-open-skins>换个年代皮肤</button></div><div class="lab-layout"><aside class="lab-note"><h2>一块小屏幕，一个大世界。</h2><p>${m.note}</p><div class="lab-shortcuts">${phoneApps.map(([id,t,i])=>`<button data-phone-app="${id}" class="${phoneState.app===id?'selected':''}">${i} ${t}</button>`).join('')}</div><p class="lab-caption">网页重制，非原厂系统模拟器。机型外观和内容年代可独立选择；没有真实电话、短信或商用下载服务。</p><p class="lab-caption">截图在本机生成，新闻、小游戏、壁纸与广告页都能保存。跨域影片和历史网页画面可能不入图。</p></aside><div class="phone-stage wallpaper-${phoneState.wallpaper}"><div class="device-shadow"></div><div class="museum-device device-${m.class}" id="museum-device"><div class="device-top"><div class="device-speaker"></div><span class="device-brand">${m.short}</span><i class="device-camera"></i></div><div class="device-screen"><div class="device-status"><span>▂▄▆ 中国移动</span><b>${date.slice(0,4)} ▰</b></div><div class="device-app-title">${phoneApps.find(x=>x[0]===phoneState.app)?.[1]||'游戏'}<span>时光网络</span></div><div class="device-viewport wallpaper-${phoneState.wallpaper}" id="device-viewport">${phoneScreen()}</div><div class="device-softkeys"><button data-phone-soft="left">${phoneState.app==='home'?'功能表':'首页'}</button><button data-phone-soft="right">${phoneState.app==='home'?'通讯录':'返回'}</button></div></div><div class="device-hinge"></div><div class="device-controls"><button class="device-call" data-phone-app="sms" aria-label="打开短信">▰</button><div class="device-dpad"><button data-phone-dir="up" aria-label="手机方向上">▲</button><button data-phone-dir="left" aria-label="手机方向左">◀</button><button data-phone-ok aria-label="手机确认">●</button><button data-phone-dir="right" aria-label="手机方向右">▶</button><button data-phone-dir="down" aria-label="手机方向下">▼</button></div><button class="device-end" data-phone-app="home" aria-label="返回手机首页">▰</button></div><div class="device-keypad">${[['1',''],['2','ABC'],['3','DEF'],['4','GHI'],['5','JKL'],['6','MNO'],['7','PQRS'],['8','TUV'],['9','WXYZ'],['*','+'],['0','␣'],['#','⇧']].map(([n,l])=>`<button data-phone-key="${n}" aria-label="手机按键 ${n}"><b>${n}</b><small>${l}</small></button>`).join('')}</div><button class="device-home-button" data-phone-app="home" aria-label="手机主屏幕"><i></i></button><div class="device-bottom-mark">${m.class==='iphone'?'Designed for memories':'OLDDAYS / STYLE RECREATION'}</div></div></div><aside class="lab-side-ad">${eraAdvertMarkup('poster',2)}<p>不是回到某个网址，<br>是回到那时的一个晚上。</p><button data-capture-phone>给这个晚上留一张截图</button></aside></div><footer class="lab-foot">${m.name} · ${year()} 内容时间 · 怀旧创作，并非历史原机画面。</footer></section>`;}
function refreshPhone(){savePhone();if(current.type!=='phone')return;const view=$('#device-viewport');if(view){view.innerHTML=phoneScreen();view.scrollTop=0;}document.querySelectorAll('[data-phone-soft]').forEach(b=>b.textContent=phoneState.app==='home'?(b.dataset.phoneSoft==='left'?'功能表':'通讯录'):(b.dataset.phoneSoft==='left'?'首页':'返回'));const title=$('.device-app-title');if(title)title.innerHTML=(phoneApps.find(x=>x[0]===phoneState.app)?.[1]||'游戏')+'<span>时光网络</span>';document.querySelectorAll('[data-phone-app]').forEach(b=>b.classList.toggle('selected',b.dataset.phoneApp===phoneState.app));}
function sendPhoneSms(text){const t=String(text||'').trim().slice(0,160);if(!t)return false;let reply='收到你的体验代码。欢迎回到那一年！这是一条本机模拟回复，没有发送真实短信。';if(/铃声|MUSIC|PHONE/i.test(t))reply='[时光服务] 你的原创铃声卡已送达。打开“音乐”听一听，声音只在本机播放，不订阅、不收费。';if(/壁纸|PHOTO/i.test(t)){reply='[时光服务] 蓝色星空壁纸已存入“我的壁纸”。按一下应用，让手机焕然一新。';phoneState.wallpaper='blue';}if(/游戏|GAME/i.test(t))reply='[时光服务] 掌中游戏厅已开启。按数字键或点方向键，贪吃蛇等你来挑战。';phoneState.sent.push({text:t,reply});phoneState.sent=phoneState.sent.slice(-12);phoneState.draft='';savePhone();return true;}
function phoneSelectApp(app){if(!phoneApps.some(x=>x[0]===app)&&app!=='snake')return;phoneState.app=app;phoneState.article=null;phoneState.page=0;refreshPhone();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-phone-lab],[data-phone-app],[data-phone-key],[data-phone-soft],[data-phone-news],[data-phone-news-back],[data-phone-send],[data-phone-wallpaper],[data-phone-snake],[data-capture-phone],[data-phone-ok],[data-phone-dir]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-phone-lab'))return openPhoneLab();if(b.hasAttribute('data-capture-phone'))return captureMuseum('phone');if(b.dataset.phoneApp){if(current.type!=='phone')return openPhoneLab(b.dataset.phoneApp);return phoneSelectApp(b.dataset.phoneApp);}if(b.dataset.phoneWallpaper){phoneState.wallpaper=b.dataset.phoneWallpaper;savePhone();return navigate(current,false);}if(b.dataset.phoneNews!==undefined){phoneState.article=Number(b.dataset.phoneNews);return refreshPhone();}if(b.hasAttribute('data-phone-news-back')){phoneState.article=null;return refreshPhone();}if(b.hasAttribute('data-phone-send')){if(sendPhoneSms($('#phone-sms-text').value)){refreshPhone();const inbox=$('#device-viewport');inbox.scrollTop=inbox.scrollHeight;toast('已收到一条模拟回复');}else toast('先写一点内容吧');return;}if(b.hasAttribute('data-phone-snake')){startPhoneSnake();return;}if(b.dataset.phoneSoft){if(b.dataset.phoneSoft==='right'&&phoneState.app==='magazines'&&phoneMagSelected){phoneMagSelected=null;return refreshPhone();}if(b.dataset.phoneSoft==='right'&&phoneState.app==='home')phoneSelectApp('sms');else phoneSelectApp('home');return;}if(b.dataset.phoneDir){if(phoneState.app==='magazines'&&phoneMagSelected&&['left','right'].includes(b.dataset.phoneDir))return phoneMagazineKey(b.dataset.phoneDir==='right'?'6':'4');if(phoneState.app==='gallery'&&phonePicture&&['left','right'].includes(b.dataset.phoneDir)){phonePicturePage=Math.max(0,Math.min(3,phonePicturePage+(b.dataset.phoneDir==='right'?1:-1)));return refreshPhone();}if(phoneState.app==='snake')snakeTurn(b.dataset.phoneDir);else $('#device-viewport').scrollBy({top:b.dataset.phoneDir==='up'?-100:b.dataset.phoneDir==='down'?100:0,behavior:'smooth'});return;}if(b.hasAttribute('data-phone-ok')){if(phoneState.app==='magazines'){if(phoneMagSelected)return phoneMagazineKey('6');phoneMagSelected=kioskAvailable()[0]?.id||null;return refreshPhone();}if(phoneState.app==='snake')toggleSnake();else phoneSelectApp('games');return;}if(b.dataset.phoneKey!==undefined){const key=b.dataset.phoneKey;if(phoneState.app==='magazines')return phoneMagazineKey(key);if(phoneState.app==='gallery'&&phonePicture){if(key==='4'||key==='6'){phonePicturePage=Math.max(0,Math.min(3,phonePicturePage+(key==='6'?1:-1)));refreshPhone();}else if(key==='2'||key==='8')$('#device-viewport').scrollBy({top:key==='2'?-100:100,behavior:'smooth'});else if(key==='0')phoneSelectApp('home');return;}if(phoneState.app==='snake'){const dir={2:'up',4:'left',6:'right',8:'down'}[key];if(dir)snakeTurn(dir);if(key==='5')toggleSnake();}else {const map={1:'news',2:'music',3:'videos',4:'books',5:'games',6:'sms',7:'ads',8:'photos',9:'gallery','#':'magazines',0:'home'};if(map[key])phoneSelectApp(map[key]);}}});
document.addEventListener('change',e=>{if(e.target.id==='phone-model-select'&&Object.hasOwn(phoneModels,e.target.value)){phoneState.model=e.target.value;savePhone();navigate(current,false);}});
